head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
scwin.vScrenID = "ULDSTF05621.xml";
scwin.vScrenTpCD = "";
scwin.Isur_cd = "", scwin.Isur_nm = "", scwin.Secugrp_id = "", scwin.Mkt_id = "", scwin.fr_bz_procs_no = "", scwin.haltTpCd = "";
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.trsIdx;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
}; // insert, update 구분

scwin.fn_search = function() {
    if (scwin.fr_bz_procs_no != "") {
        var url = "/fiscalYearChange.do";
        url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=searchFiscalYearChange&DIV_IDX=" + DIV_IDX_FSC_MST + "&BZ_PROCS_NO=" + scwin.fr_bz_procs_no;
        dts_Mst.DataID = encodeURI(url);
        dts_Mst.reset();
        url = "/fiscalYearChange.do";
        url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=searchFiscalYearChange&DIV_IDX=" + DIV_IDX_DTL_DIST_BF + "&BZ_PROCS_NO=" + scwin.fr_bz_procs_no;
        dts_DtlBf.DataID = encodeURI(url);
        dts_DtlBf.reset();
        url = "/fiscalYearChange.do";
        url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=searchFiscalYearChange&DIV_IDX=" + DIV_IDX_DTL_DIST_AF + "&BZ_PROCS_NO=" + scwin.fr_bz_procs_no;
        dts_DtlAf.DataID = encodeURI(url);
        dts_DtlAf.reset();
    }
};
scwin.fn_new_onload = function() {
    dts_Mst.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=FSCCHG_MST_INOUT";
    dts_Mst.reset();
    dts_DtlAf.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=FSCCHG_DTL_INOUT";
    dts_DtlAf.reset();

    /* useupdate를 false로 지정함. */
    var url = "/fiscalYearChange.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=searchFiscalYearChange&DIV_IDX=" + DIV_IDX_DTL_DIST_BF + "&TRS_IDX=" + TRS_IDX_NEWSEL2 + "&ISUR_CD=" + scwin.Isur_cd;
    dts_DtlBf.DataID = encodeURI(url); /* 관련종목을 모두 담고 SELECT 컬럼의 플래그로 선택여부를 확인한다. */
    dts_DtlBf.reset();
};
scwin.fn_CheckForm = function() {
    for (i = 1; i <= dts_DtlAf.getTotalRow(); i++) {
        dts_DtlAf.setCellData(i, "BAS_MMDD", dts_DtlAf.getCellData(i, "BAS_MM") + dts_DtlAf.getCellData(i, "BAS_DD"));
        if (dts_DtlAf.getCellData(i, "BAS_MMDD") != "" && dts_DtlAf.getCellData(i, "BAS_MMDD").length != 4) {
            $c.win.alert("입력한 항목중 [변경후(월,일)]을 정확히 입력해주세요. \n\n예 : 5월1일 -> 0501 ");
            return false;
        }
    }
    if (edt_CHG_DD.text.length != 8) {
        $c.win.alert("[변경일]을 정확히 입력하세요.");
        edt_CHG_DD.focus();
        return false;
    }
    if (!$c.lc.checkDdTm("DD", edt_MKTACT_ENFORCE_DD, "시장조치시행", false)) return false;
    if (cmb_FISCYY_CHG_RSN_CD.BindColVal == "") {
        $c.win.alert("[변경사유]를  선택해주세요");
        cmb_FISCYY_CHG_RSN_CD.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txa_REMK, 2000, "기타")) return false;
    return true;
};
scwin.fn_save_trs = function() {
    if (scwin.trsIdx == '1') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_02;
    } else if (scwin.trsIdx == '2') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_03;
    } else if (scwin.trsIdx == '3') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_04;
    }

    //시장조치시행일가 변경일자가 다름.
    //dts_Mst.NameString(dts_Mst.RowPosition, "CHG_DD") = dts_Mst.NameString(dts_Mst.RowPosition, "MKTACT_ENFORCE_DD");

    for (i = 1; i <= dts_DtlAf.getTotalRow(); i++) {
        if (dts_DtlAf.getCellData(i, "BAS_MMDD") == "") {
            $c.cp.removeRow(dts_DtlAf, i);
            i--; // 삭제한 경우는 해당하는 위치에서 한번더 검색하게 함.

        }
    }

    //매매거래정지 사유는 매번 업무처리 번호를 세팅함
    //사유별 추가,삭제가 있을수 있기때문
    for (var i = 1; i <= dts_DtlBf.getTotalRow(); i++) {

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************

        dts_DtlBf.setCellData(i, "BZ_PROCS_NO", /*ORG SRC: dts_DtlBf.setNameString(i, "BZ_PROCS_NO", dts_DtlBf.NameString(i, "BZ_PROCS_NO") = );*/ X = X);
        dts_DtlBf.setCellData(i, "BYBZPROCS_SEQ", eval(i + 0));
        dts_DtlBf.setCellData(i, "ISUR_CD", /*ORG SRC: dts_DtlBf.setNameString(i, "ISUR_CD", dts_DtlBf.NameString(i, "ISUR_CD") = );*/ X = X);
        dts_DtlBf.setCellData(i, "CHG_BFAF_TP_CD", "1"); // 변경전후구분코드 , 1:변경전 , 2:변경후

    }
    for (var i = 1; i <= dts_DtlAf.getTotalRow(); i++) {

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************

        dts_DtlAf.setCellData(i, "BZ_PROCS_NO", /*ORG SRC: dts_DtlAf.setNameString(i, "BZ_PROCS_NO", dts_DtlAf.NameString(i, "BZ_PROCS_NO") = );*/ X = X);
        dts_DtlAf.setCellData(i, "BYBZPROCS_SEQ", eval(i + 12));
        dts_DtlAf.setCellData(i, "ISUR_CD", /*ORG SRC: dts_DtlAf.setNameString(i, "ISUR_CD", dts_DtlAf.NameString(i, "ISUR_CD") = );*/ X = X);
        dts_DtlAf.setCellData(i, "CHG_BFAF_TP_CD", "2"); // 변경전후구분코드 , 1:변경전 , 2:변경후

    }

    //alert(dts_DtlBf.Text );
    //alert(dts_DtlAf.Text );
    trs.Action = $c.lc.fn_encodeNSession("/fiscalYearChange.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + scwin.vScrenTpCD + "&method=saveFiscalYearChange");
    trs.KeyName = "toinb_dataid4";
    trs.KeyValue = "JSP(I: dtsParm1= dts_Mst , I:dtsParm2= dts_DtlAf, I:dtsParm3= dts_DtlBf)";
    trs.Parameters = "TRS_IDX=" + scwin.trsIdx + ",BZ_PROCS_NO=" + scwin.fr_bz_procs_no + ",COUNT=3" + ",LIST_BZ_TP_CD=" + LIST_BZ_TP_CD_232 + ",DIV_IDX[0]=" + DIV_IDX_FSC_MST + ",DIV_IDX[1]=" + DIV_IDX_DTL_DIST_AF + ",DIV_IDX[2]=" + DIV_IDX_DTL_DIST_BF;
    trs.Post();
};
scwin.fn_save = function() {
    if (scwin.fn_CheckForm()) {
        if (!$c.lc.fn_isProcess('I')) return;
        if (!$c.lc.fn_mst_check(dts_Mst_Check, "2")) return;
        scwin.fr_bz_procs_no = $c.stf.fn_getNewBzProcNo(dts_BzProcsNo);
        if (scwin.fr_bz_procs_no.length != 14) {
            $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        } else {
            scwin.trsIdx = TRS_IDX_INSERT;
            dts_Mst.setCellData(dts_Mst.getRowPosition(), "BZ_PROCS_NO", scwin.fr_bz_procs_no);
            dts_Mst.setCellData(dts_Mst.getRowPosition(), "ISUR_CD", scwin.Isur_cd);
            dts_Mst.setCellData(dts_Mst.getRowPosition(), "FISCYY_DISTR_BASDD_TP_CD", "2"); // 1:결산기 , 2:수입분배기준일

            scwin.fn_save_trs();
        }
    }
};
scwin.fn_update = function() {
    if (scwin.fn_CheckForm()) {
        scwin.trsIdx = TRS_IDX_UPDATE;
        if ($c.cp.isModified(dts_Mst) || $c.cp.isModified(dts_DtlAf)) {
            if (!$c.lc.fn_isProcess('U')) return;
            scwin.fn_save_trs();
        } else {
            $c.lc.fn_alertNoUpdate();
        }
    }
};
scwin.fn_delete = function() {
    if (!$c.lc.fn_isProcess('D')) return;
    buttonSet.setDeleteStatus(); // buttonSet에 CRUD상태를 저장하여 이용하는 사례, TR의 응답event에서 사용.

    scwin.trsIdx = TRS_IDX_DELETE;
    scwin.fn_save_trs();
};
scwin.fn_dscl = async function() {
    var OldGet = scwin.fn_GetPar;
    var OldSet = scwin.fn_SetPar;
    scwin.fn_GetPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3) {
        arr[0] = "68212C";
        arr[1] = scwin.fr_bz_procs_no;
        arr[2] = scwin.Isur_cd;
        arr[3] = '1';

        //CopyDataSet( dts_Isu , param_dts_isu);
        $c.stf.CopyDataSet(dts_Mst, param_dts_mst);
        $c.stf.CopyDataSet(dts_DtlBf, param_dts2);
        $c.stf.CopyDataSet(dts_DtlAf, param_dts3);
        for (var i = 1; i <= param_dts3.getTotalRow(); i++) {
            if ((param_dts3.getCellData(i, "BAS_MM") == "") && (param_dts3.getCellData(i, "BAS_DD") == "")) {
                param_dts3.DeleteRow(i);
                i--;
            }
        }
        return arr.length;
    };
    scwin.fn_SetPar = function(arr) {

    };
    var wth = 730 + 5;
    var hgt = 785 + 30;
    var pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    await $c.frame.CreateDialogFrame("ULDSTF92024", "/listingcommon/ULDSTF92024.gfm", "공시안내문작성", pt.x, pt.y, wth, hgt, "window");
    scwin.fn_GetPar = OldGet;
    scwin.fn_SetPar = OldSet;
};
scwin.fn_drft = function() {
    var OldGet = scwin.fn_GetPar;
    scwin.fn_GetPar = function(arr) {
        arr[0] = scwin.fr_bz_procs_no;
        return arr.length;
    };
    $c.lc.fn_PopFindDraft();
    scwin.fn_GetPar = OldGet;
};
scwin.fn_makt = function() {

};
scwin.trs_OnFail = function() {
    $c.lc.fn_alertMsg('F');
};
scwin.trs_OnSuccess = async function() {
    $c.lc.fn_alertMsg('S');
    if (buttonSet.status == "D") {
        // 삭제처리의 응답인 경우
        await $c.frame.CloseFrame();
    } else {
        scwin.fn_search();
    }
};
scwin.dts_Mst_OnLoadCompleted = function(rowcount) {
    if (scwin.fr_bz_procs_no == "") {
        dts_Mst.insertRow();
    }

    // 신규처리에 의한 조회인지,  수정에 의한 조회인지를 구별
    if (scwin.fr_bz_procs_no == "") {
        buttonSet.setInsertStatus();
    } else {
        $c.stf.setButtonSetWithDate(edt_MKTACT_ENFORCE_DD, false);
    }

    //alert(" dts_TrdSsp OnLoadCompleted \n" + dts_TrdSsp.Text  + "\n\n" + fn_logDSet(dts_TrdSsp) ); 

};
scwin.dts_DtlBf_OnLoadCompleted = function(rowcount) {
    //	alert(dts_DtlBf.Text);

};
scwin.dts_DtlAf_OnLoadCompleted = function(rowcount) {
    // 변경후는 항상 12개 row를 생성해줌
    for (var i = dts_DtlAf.getTotalRow(); i < 13; i++) {
        dts_DtlAf.insertRow();
    }
};
scwin.img_MKTACT_ENFORCE_DD_onclick = function() {
    popUpCalendar2(edt_MKTACT_ENFORCE_DD);
};
scwin.img_CHG_DD_onclick = function() {
    popUpCalendar2(edt_CHG_DD);
};
scwin.grd_DIST_PAY_AF_OnExit = function(row, colid, olddata) {
    //alert('MxGrid_1.OnExit('+row+','+ colid+','+ olddata+')');
    if (colid == "BAS_MM" && eval(dts_DtlAf.getCellData(row, "BAS_MM")) > 12) {
        $c.win.alert("입력월을 확인하세요.");
        dts_DtlAf.setCellData(row, "BAS_MM", "");
    } else if (colid == "BAS_DD" && eval(dts_DtlAf.getCellData(row, "BAS_DD")) > 31) {
        $c.win.alert("입력일을 확인하세요.");
        dts_DtlAf.setCellData(row, "BAS_DD", "");
    }
};
scwin.img_ChgStatDd_onclick = function() {
    popUpCalendar2(edt_ChgStatDd);
};
scwin.img_ChgEndDd_onclick = function() {
    popUpCalendar2(edt_ChgEndDd);
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.gform_onload = function() {
    var fnc = $c.frame.path("../").scwin.fn_GetPar; // Provider화면에서 fn_GetPar명칭으로 선언된 함수를 획득
    var arrPar = new Array();
    if (fnc != undefined) {
        fnc(arrPar); // Provider화면의 callback함수를 호출하여 필요한 인수를 넘겨받는다.
        scwin.Isur_cd = (arrPar.length >= 1 ? arrPar[0] : ""); // 발행기관코드
        scwin.Isur_nm = (arrPar.length >= 2 ? arrPar[1] : ""); // 발행기관명
        scwin.Secugrp_id = (arrPar.length >= 3 ? arrPar[2] : ""); // 증권그룹ID
        scwin.Mkt_id = (arrPar.length >= 4 ? arrPar[3] : ""); // 시장구분코드
        scwin.fr_bz_procs_no = (arrPar.length >= 5 ? arrPar[4] : ""); // 업무처리번호(수정시만 유효)
        scwin.haltTpCd = (arrPar.length >= 6 ? arrPar[5] : ""); // 결산기분배기준일구분코드 1 : 결산기, 2 : 분배기준일

    }

    //alert( "Isur_cd =  " +Isur_cd + "\n"  + " Isur_nm = " + Isur_nm + "\n" + "  Secugrp_id = " + Secugrp_id + "\n" + 
    //		 "Mkt_id =  " +Mkt_id + "\n" + " fr_bz_procs_no = " + fr_bz_procs_no+ "\n"  );

    /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
    buttonSet.setSaveInfo(btn_Save, fn_save); // 저장
    buttonSet.setUpdateInfo(btn_Update, fn_update); // 수정
    buttonSet.setDeleteInfo(btn_Delete, fn_delete); // 삭제
    buttonSet.setDsclInfo(btn_Dscl, fn_dscl); // 안내문작성
    buttonSet.setDrftInfo(btn_Drft, fn_drft); // 기안

    if (scwin.fr_bz_procs_no != "") {
        // Provider화면 에서 넘겨받은 업무처리번호가 ""가 아니라면 신규작성으로 간주한다.
        scwin.fn_search();
    } else {
        scwin.fn_new_onload(); // 신규작성시 호출

    }
    dts_Mst.setCellData(dts_Mst.getRowPosition(), "ISUR_CD", scwin.Isur_cd);
    dts_Mst.setCellData(dts_Mst.getRowPosition(), "ISUR_NM", scwin.Isur_nm);
    $c.cm.PanelToGroupBox(panel_3);
};
scwin.grd_DIST_PAY_AF_CanColumnPosChange = function(row, colid) {
    return true;
};
